CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,email_verified boolean NOT NULL DEFAULT false,image text,role text NOT NULL DEFAULT 'buyer' CONSTRAINT user_role_valid CHECK (role IN ('buyer','seller','admin')),location text NOT NULL DEFAULT '',seller_verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "session" (id text PRIMARY KEY,expires_at timestamptz NOT NULL,token text NOT NULL UNIQUE,ip_address text,user_agent text,user_id text NOT NULL REFERENCES "user"(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY,account_id text NOT NULL,provider_id text NOT NULL,user_id text NOT NULL REFERENCES "user"(id),access_token text,refresh_token text,id_token text,access_token_expires_at timestamptz,refresh_token_expires_at timestamptz,scope text,password text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS listing (id serial PRIMARY KEY,seller_id text NOT NULL REFERENCES "user"(id),title text NOT NULL,brand text NOT NULL,model text NOT NULL,category text NOT NULL,condition text NOT NULL,board_class text NOT NULL DEFAULT 'Grade A (Complete / All ICs)',storage_gb text NOT NULL DEFAULT '128GB',ram_gb text NOT NULL DEFAULT '6GB',ic_code text,description text NOT NULL,diagnostics text NOT NULL,price_centavos integer NOT NULL CONSTRAINT listing_price_valid CHECK (price_centavos BETWEEN 100 AND 99999999),quantity integer NOT NULL CONSTRAINT listing_quantity_valid CHECK (quantity >= 0),minimum_quantity integer NOT NULL CONSTRAINT listing_minimum_valid CHECK (minimum_quantity BETWEEN 1 AND 10000),art text NOT NULL DEFAULT 'board',is_active boolean NOT NULL DEFAULT true,stock_version integer NOT NULL DEFAULT 0 CONSTRAINT listing_version_valid CHECK (stock_version >= 0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "order" (id serial PRIMARY KEY,buyer_id text NOT NULL REFERENCES "user"(id),listing_id integer NOT NULL REFERENCES listing(id),quantity integer NOT NULL CONSTRAINT order_quantity_valid CHECK (quantity BETWEEN 1 AND 10000),total_centavos bigint NOT NULL CONSTRAINT order_total_valid CHECK (total_centavos > 0 AND total_centavos <= 9007199254740991),platform_fee_rate integer NOT NULL DEFAULT 800,platform_fee_centavos bigint NOT NULL DEFAULT 0,seller_payout_centavos bigint NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'reserved' CONSTRAINT order_status_valid CHECK (status IN ('reserved','shipped','inspection','completed','disputed','cancelled')),address text NOT NULL,courier text,tracking_number text,received_at timestamptz,dispute text,listing_snapshot jsonb NOT NULL,reservation_key text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS buyer_reservation_unique ON "order" (buyer_id,reservation_key);
CREATE UNIQUE INDEX IF NOT EXISTS account_provider_unique ON account (provider_id,account_id);
CREATE INDEX IF NOT EXISTS listing_seller_index ON listing (seller_id);
CREATE INDEX IF NOT EXISTS order_buyer_index ON "order" (buyer_id);
CREATE INDEX IF NOT EXISTS order_listing_index ON "order" (listing_id);
ALTER TABLE listing ADD COLUMN IF NOT EXISTS board_class text NOT NULL DEFAULT 'Grade A (Complete / All ICs)';
ALTER TABLE listing ADD COLUMN IF NOT EXISTS storage_gb text NOT NULL DEFAULT '128GB';
ALTER TABLE listing ADD COLUMN IF NOT EXISTS ram_gb text NOT NULL DEFAULT '6GB';
ALTER TABLE listing ADD COLUMN IF NOT EXISTS ic_code text;
ALTER TABLE "order" ADD COLUMN IF NOT EXISTS platform_fee_rate integer NOT NULL DEFAULT 800;
ALTER TABLE "order" ADD COLUMN IF NOT EXISTS platform_fee_centavos bigint NOT NULL DEFAULT 0;
ALTER TABLE "order" ADD COLUMN IF NOT EXISTS seller_payout_centavos bigint NOT NULL DEFAULT 0;
UPDATE "order" SET platform_fee_rate = 800, platform_fee_centavos = ROUND((total_centavos * 8) / 100), seller_payout_centavos = total_centavos - ROUND((total_centavos * 8) / 100) WHERE platform_fee_centavos = 0 AND total_centavos > 0;

